import bisect
import re
from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_DOW_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

_INT_RE = re.compile(r"[0-9]+")
_WHITESPACE_RE = re.compile(r"[ \t]+")


def _parse_step(token: str) -> int:
    if not _INT_RE.fullmatch(token):
        raise ValueError
    value = int(token)
    if value < 1:
        raise ValueError
    return value


def _parse_endpoint(
    token: str,
    field_min: int,
    field_max: int,
    name_map: dict[str, int] | None,
) -> int:
    if _INT_RE.fullmatch(token):
        value = int(token)
        if value < field_min or value > field_max:
            raise ValueError
        return value

    if name_map is not None:
        upper = token.upper()
        if upper in name_map:
            value = name_map[upper]
            if value < field_min or value > field_max:
                raise ValueError
            return value

    raise ValueError


def _parse_item(
    item: str,
    field_min: int,
    field_max: int,
    name_map: dict[str, int] | None,
    is_dow: bool,
) -> set[int]:
    if item == "":
        raise ValueError

    values: set[int] = set()

    def add_raw_values(raw_values: range) -> None:
        for raw in raw_values:
            if is_dow and raw == 7:
                raw = 0
            values.add(raw)

    if "/" in item:
        if item.count("/") != 1:
            raise ValueError

        range_part, step_part = item.split("/", 1)
        step = _parse_step(step_part)

        if range_part == "*":
            add_raw_values(range(field_min, field_max + 1, step))
            return values

        if "-" in range_part:
            if range_part.count("-") != 1:
                raise ValueError

            left, right = range_part.split("-", 1)
            a = _parse_endpoint(left, field_min, field_max, name_map)
            b = _parse_endpoint(right, field_min, field_max, name_map)
            if a > b:
                raise ValueError

            add_raw_values(range(a, b + 1, step))
            return values

        raise ValueError

    if item == "*":
        add_raw_values(range(field_min, field_max + 1))
        return values

    if "-" in item:
        if item.count("-") != 1:
            raise ValueError

        left, right = item.split("-", 1)
        a = _parse_endpoint(left, field_min, field_max, name_map)
        b = _parse_endpoint(right, field_min, field_max, name_map)
        if a > b:
            raise ValueError

        add_raw_values(range(a, b + 1))
        return values

    single = _parse_endpoint(item, field_min, field_max, name_map)
    add_raw_values(range(single, single + 1))
    return values


def _parse_field(
    field: str,
    field_min: int,
    field_max: int,
    name_map: dict[str, int] | None,
    is_dow: bool,
) -> set[int]:
    if field == "":
        raise ValueError

    values: set[int] = set()
    for item in field.split(","):
        if item == "":
            raise ValueError
        values.update(_parse_item(item, field_min, field_max, name_map, is_dow))

    if not values:
        raise ValueError
    return values


def next_run(expression: str, after: datetime) -> datetime | None:
    stripped = expression.strip(" \t")
    if not stripped:
        raise ValueError

    fields = _WHITESPACE_RE.split(stripped)
    if len(fields) != 5:
        raise ValueError

    minute_field, hour_field, day_field, month_field, dow_field = fields

    minute_values = _parse_field(minute_field, 0, 59, None, False)
    hour_values = _parse_field(hour_field, 0, 23, None, False)

    day_no_spec = day_field == "*"
    month_values = _parse_field(month_field, 1, 12, _MONTH_NAMES, False)
    dow_no_spec = dow_field == "*"

    day_values = _parse_field(day_field, 1, 31, None, False)
    dow_values = _parse_field(dow_field, 0, 7, _DOW_NAMES, True)

    time_pairs = sorted(
        (hour, minute)
        for hour in sorted(hour_values)
        for minute in sorted(minute_values)
    )

    try:
        start_dt = (after + timedelta(minutes=1)).replace(second=0, microsecond=0)
    except OverflowError:
        return None

    max_year = after.year + 10
    if max_year > datetime.max.year:
        max_year = datetime.max.year

    if max_year < start_dt.year:
        return None

    max_date = date(max_year, 12, 31)
    current_date = start_dt.date()
    start_date = start_dt.date()

    if current_date > max_date:
        return None

    valid_months = sorted(month_values)

    while current_date <= max_date:
        month_index = bisect.bisect_left(valid_months, current_date.month)
        if month_index == len(valid_months) or valid_months[month_index] != current_date.month:
            if month_index < len(valid_months):
                next_year = current_date.year
                next_month = valid_months[month_index]
            else:
                next_year = current_date.year + 1
                next_month = valid_months[0]

            if next_year > max_year:
                return None

            current_date = date(next_year, next_month, 1)
            continue

        cron_dow = (current_date.weekday() + 1) % 7

        if day_no_spec and dow_no_spec:
            pass
        elif day_no_spec:
            if cron_dow not in dow_values:
                if current_date == max_date:
                    break
                current_date += timedelta(days=1)
                continue
        elif dow_no_spec:
            if current_date.day not in day_values:
                if current_date == max_date:
                    break
                current_date += timedelta(days=1)
                continue
        else:
            if (current_date.day not in day_values) and (cron_dow not in dow_values):
                if current_date == max_date:
                    break
                current_date += timedelta(days=1)
                continue

        if current_date == start_date:
            lower_bound = (start_dt.hour, start_dt.minute)
            time_index = bisect.bisect_left(time_pairs, lower_bound)

            if time_index == len(time_pairs):
                if current_date == max_date:
                    break
                current_date += timedelta(days=1)
                continue

            hour, minute = time_pairs[time_index]
            candidate = datetime(
                current_date.year,
                current_date.month,
                current_date.day,
                hour,
                minute,
                0,
                0,
            )

            if candidate <= after:
                if current_date == max_date:
                    break
                current_date += timedelta(days=1)
                continue

            if candidate.year > max_year:
                return None

            return candidate

        hour, minute = time_pairs[0]
        candidate = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            hour,
            minute,
            0,
            0,
        )

        if candidate.year > max_year:
            return None

        return candidate

    return None
